BEGIN;
CREATE TABLE IF NOT EXISTS career_tenant_memberships(tenant_id TEXT NOT NULL,user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('student','guardian','counselor','integration_admin','tenant_admin')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS career_plans(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,learner_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','submitted','changes_requested','approved','active','paused','completed')),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),plan JSONB NOT NULL CHECK(jsonb_typeof(plan)='object'),idempotency_key TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS career_plan_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,plan_id BIGINT NOT NULL REFERENCES career_plans(id),actor_id BIGINT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS career_sync_requests(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,plan_id BIGINT NOT NULL REFERENCES career_plans(id),provider TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','processing','succeeded','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,requested_by BIGINT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS career_plans_tenant_state_idx ON career_plans(tenant_id,state);CREATE INDEX IF NOT EXISTS career_sync_pending_idx ON career_sync_requests(status,created_at);
COMMIT;
